-- Phase 3: tickets, threaded messages, SLA targets, an audit trail, and the
-- inbound-email ingestion function used by the Resend webhook.

create type public.ticket_status as enum ('new', 'open', 'pending', 'on_hold', 'solved', 'closed');
create type public.ticket_priority as enum ('low', 'normal', 'high', 'urgent');
create type public.ticket_channel as enum ('email', 'web', 'chat', 'phone');
-- customer: from the requester; agent: a staff reply the requester sees;
-- note: internal only; system: generated by the app.
create type public.message_kind as enum ('customer', 'agent', 'note', 'system');

-- ---------------------------------------------------------------------------
-- SLA policies: targets per client tier and ticket priority. Tickets without
-- a matched client use the 'standard' tier.
-- ---------------------------------------------------------------------------

create table public.sla_policies (
  sla_tier public.sla_tier not null,
  priority public.ticket_priority not null,
  first_response_minutes integer not null check (first_response_minutes > 0),
  resolution_minutes integer not null check (resolution_minutes > 0),
  primary key (sla_tier, priority)
);

insert into public.sla_policies (sla_tier, priority, first_response_minutes, resolution_minutes) values
  ('standard',   'low',    2880, 14400), ('standard',   'normal', 1440, 7200),
  ('standard',   'high',    480, 2880),  ('standard',   'urgent',  240, 1440),
  ('priority',   'low',    1440, 7200),  ('priority',   'normal',  480, 2880),
  ('priority',   'high',    240, 1440),  ('priority',   'urgent',   60,  480),
  ('enterprise', 'low',     480, 2880),  ('enterprise', 'normal',  240, 1440),
  ('enterprise', 'high',     60,  480),  ('enterprise', 'urgent',   30,  240);

-- ---------------------------------------------------------------------------
-- Tables
-- ---------------------------------------------------------------------------

create table public.tickets (
  id uuid primary key default gen_random_uuid(),
  -- Human reference, shown as BC-1000.
  number bigint generated always as identity (start with 1000) unique,
  -- Unguessable token in the per-ticket reply address (support+<token>@...).
  reply_token text not null unique default encode(extensions.gen_random_bytes(12), 'hex'),
  subject text not null check (length(trim(subject)) > 0),
  status public.ticket_status not null default 'new',
  priority public.ticket_priority not null default 'normal',
  channel public.ticket_channel not null default 'web',
  client_id uuid references public.clients (id) on delete set null,
  product_id uuid references public.products (id) on delete set null,
  assignee_id uuid references public.staff (id) on delete set null,
  requester_email text not null check (requester_email = lower(requester_email)),
  requester_name text not null default '',
  tags text[] not null default '{}',
  first_response_due_at timestamptz,
  resolution_due_at timestamptz,
  first_responded_at timestamptz,
  solved_at timestamptz,
  last_customer_message_at timestamptz,
  last_agent_message_at timestamptz,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
create index tickets_status_idx on public.tickets (status);
create index tickets_assignee_idx on public.tickets (assignee_id);
create index tickets_client_idx on public.tickets (client_id);
create index tickets_requester_idx on public.tickets (requester_email);

create table public.ticket_messages (
  id uuid primary key default gen_random_uuid(),
  ticket_id uuid not null references public.tickets (id) on delete cascade,
  kind public.message_kind not null,
  author_staff_id uuid references public.staff (id) on delete set null,
  author_email text not null default '',
  author_name text not null default '',
  body_text text not null default '',
  body_html text,
  -- RFC 5322 Message-ID (inbound: the sender's; outbound: the one we set).
  email_message_id text unique,
  resend_email_id text unique,
  created_at timestamptz not null default now()
);
create index ticket_messages_ticket_idx on public.ticket_messages (ticket_id, created_at);

create table public.ticket_events (
  id bigint generated always as identity primary key,
  ticket_id uuid not null references public.tickets (id) on delete cascade,
  actor_id uuid references public.staff (id) on delete set null,
  event text not null,
  from_value text,
  to_value text,
  created_at timestamptz not null default now()
);
create index ticket_events_ticket_idx on public.ticket_events (ticket_id, created_at);

-- ---------------------------------------------------------------------------
-- Functions
-- ---------------------------------------------------------------------------

-- The client whose domain matches this email address, trying the exact domain
-- first and then parent domains (mail.addis.example -> addis.example).
create function public.match_client_by_email(email text)
returns uuid
language plpgsql
stable
security definer
set search_path = ''
as $$
declare
  dom text := lower(split_part(email, '@', 2));
  found uuid;
begin
  while dom like '%.%' loop
    select d.client_id into found
    from public.client_domains d
    join public.clients c on c.id = d.client_id and c.active
    where d.domain = dom;
    if found is not null then
      return found;
    end if;
    dom := substring(dom from position('.' in dom) + 1);
  end loop;
  return null;
end;
$$;

-- Fill in client (from the requester's domain) and SLA due dates.
create function public.tickets_before_write()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  tier public.sla_tier;
  policy public.sla_policies;
begin
  if tg_op = 'INSERT' and new.client_id is null then
    new.client_id := public.match_client_by_email(new.requester_email);
  end if;

  if tg_op = 'INSERT' or new.priority is distinct from old.priority or new.client_id is distinct from old.client_id then
    select coalesce((select sla_tier from public.clients where id = new.client_id), 'standard') into tier;
    select * into policy from public.sla_policies where sla_tier = tier and priority = new.priority;
    new.first_response_due_at := new.created_at + make_interval(mins => policy.first_response_minutes);
    new.resolution_due_at := new.created_at + make_interval(mins => policy.resolution_minutes);
  end if;

  if tg_op = 'UPDATE' then
    new.updated_at := now();
    if new.status = 'solved' and old.status <> 'solved' then
      new.solved_at := now();
    elsif new.status not in ('solved', 'closed') then
      new.solved_at := null;
    end if;
  end if;
  return new;
end;
$$;

create trigger tickets_before_write before insert or update on public.tickets
  for each row execute function public.tickets_before_write();

-- Audit trail of who changed what.
create function public.tickets_log_changes()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
declare
  actor uuid := (select auth.uid());
begin
  if tg_op = 'INSERT' then
    insert into public.ticket_events (ticket_id, actor_id, event, to_value)
    values (new.id, actor, 'created', new.channel::text);
    return new;
  end if;
  if new.status is distinct from old.status then
    insert into public.ticket_events (ticket_id, actor_id, event, from_value, to_value)
    values (new.id, actor, 'status', old.status::text, new.status::text);
  end if;
  if new.priority is distinct from old.priority then
    insert into public.ticket_events (ticket_id, actor_id, event, from_value, to_value)
    values (new.id, actor, 'priority', old.priority::text, new.priority::text);
  end if;
  if new.assignee_id is distinct from old.assignee_id then
    insert into public.ticket_events (ticket_id, actor_id, event, from_value, to_value)
    values (new.id, actor, 'assignee', old.assignee_id::text, new.assignee_id::text);
  end if;
  if new.client_id is distinct from old.client_id then
    insert into public.ticket_events (ticket_id, actor_id, event, from_value, to_value)
    values (new.id, actor, 'client', old.client_id::text, new.client_id::text);
  end if;
  if new.product_id is distinct from old.product_id then
    insert into public.ticket_events (ticket_id, actor_id, event, from_value, to_value)
    values (new.id, actor, 'product', old.product_id::text, new.product_id::text);
  end if;
  return new;
end;
$$;

create trigger tickets_log_changes after insert or update on public.tickets
  for each row execute function public.tickets_log_changes();

-- Keep ticket timestamps/status in step with the conversation:
-- a customer message reopens a pending/solved ticket; the first agent reply
-- records the first response and moves a new ticket to open.
create function public.ticket_messages_after_insert()
returns trigger
language plpgsql
security definer
set search_path = ''
as $$
begin
  if new.kind = 'customer' then
    update public.tickets
    set last_customer_message_at = new.created_at,
        status = case when status in ('pending', 'solved') then 'open' else status end
    where id = new.ticket_id;
  elsif new.kind = 'agent' then
    update public.tickets
    set last_agent_message_at = new.created_at,
        first_responded_at = coalesce(first_responded_at, new.created_at),
        status = case when status = 'new' then 'open' else status end
    where id = new.ticket_id;
  end if;
  return new;
end;
$$;

create trigger ticket_messages_after_insert after insert on public.ticket_messages
  for each row execute function public.ticket_messages_after_insert();

-- Turn one inbound email into a new ticket or a reply on an existing one.
-- Called by the Resend webhook (apps/support/api) with the service role only.
-- Threading, in order: the per-ticket reply address token, a [BC-1234]
-- subject reference, then In-Reply-To/References matching a stored message.
-- A match only counts if the sender is the requester or belongs to the
-- ticket's client; otherwise (or if the ticket is closed) a new ticket opens,
-- so guessing a ticket number can't inject messages into someone's ticket.
create function public.ingest_inbound_email(payload jsonb)
returns jsonb
language plpgsql
security definer
set search_path = ''
as $$
declare
  sender text := lower(trim(payload ->> 'from_email'));
  v_subject text := coalesce(nullif(trim(payload ->> 'subject'), ''), '(no subject)');
  token text;
  ref_number bigint;
  t public.tickets;
  existing uuid;
  created boolean := false;
  addr text;
begin
  if sender is null or sender not like '%@%' then
    raise exception 'from_email is required' using errcode = 'check_violation';
  end if;

  -- Idempotent: Resend retries webhooks.
  select ticket_id into existing from public.ticket_messages
  where resend_email_id = payload ->> 'resend_email_id';
  if existing is not null then
    select * into t from public.tickets where id = existing;
    return jsonb_build_object('ticket_id', t.id, 'number', t.number, 'created', false, 'duplicate', true);
  end if;

  for addr in select jsonb_array_elements_text(coalesce(payload -> 'to', '[]'::jsonb)) loop
    token := substring(lower(addr) from '\+([0-9a-f]{24})@');
    exit when token is not null;
  end loop;
  if token is not null then
    select * into t from public.tickets where reply_token = token;
  end if;

  if t.id is null then
    ref_number := substring(v_subject from '\[BC-([0-9]+)\]')::bigint;
    if ref_number is not null then
      select * into t from public.tickets where number = ref_number;
    end if;
  end if;

  if t.id is null and (payload ? 'in_reply_to' or payload ? 'references') then
    select tk.* into t
    from public.ticket_messages m
    join public.tickets tk on tk.id = m.ticket_id
    where m.email_message_id = payload ->> 'in_reply_to'
       or m.email_message_id in (select jsonb_array_elements_text(coalesce(payload -> 'references', '[]'::jsonb)))
    order by m.created_at desc
    limit 1;
  end if;

  if t.id is not null and (
       t.status = 'closed'
       or not (sender = t.requester_email
               or (t.client_id is not null and public.match_client_by_email(sender) = t.client_id))
     ) then
    t := null;
  end if;

  if t.id is null then
    insert into public.tickets (subject, channel, requester_email, requester_name)
    values (
      left(regexp_replace(v_subject, '^((re|fwd?|aw)\s*:\s*)+', '', 'i'), 300),
      'email', sender, coalesce(payload ->> 'from_name', '')
    )
    returning * into t;
    created := true;
  end if;

  insert into public.ticket_messages (
    ticket_id, kind, author_email, author_name, body_text, body_html, email_message_id, resend_email_id
  ) values (
    t.id, 'customer', sender, coalesce(payload ->> 'from_name', ''),
    coalesce(payload ->> 'text', ''), payload ->> 'html',
    nullif(payload ->> 'message_id', ''), payload ->> 'resend_email_id'
  )
  on conflict (email_message_id) do nothing;

  return jsonb_build_object('ticket_id', t.id, 'number', t.number, 'created', created, 'duplicate', false);
end;
$$;

revoke execute on function public.ingest_inbound_email(jsonb) from public, anon, authenticated;
grant execute on function public.ingest_inbound_email(jsonb) to service_role;
revoke execute on function public.match_client_by_email(text) from public, anon;
grant execute on function public.match_client_by_email(text) to authenticated, service_role;

-- ---------------------------------------------------------------------------
-- Row-level security
-- ---------------------------------------------------------------------------

alter table public.sla_policies enable row level security;
alter table public.tickets enable row level security;
alter table public.ticket_messages enable row level security;
alter table public.ticket_events enable row level security;

revoke all on public.sla_policies, public.tickets, public.ticket_messages, public.ticket_events from anon;

grant select on public.sla_policies, public.tickets, public.ticket_messages, public.ticket_events to authenticated;
grant update on public.sla_policies to authenticated;
grant insert (subject, priority, channel, client_id, product_id, assignee_id, requester_email, requester_name, tags)
  on public.tickets to authenticated;
grant update (subject, status, priority, client_id, product_id, assignee_id, tags) on public.tickets to authenticated;
grant delete on public.tickets to authenticated;
grant insert (ticket_id, kind, author_staff_id, author_email, author_name, body_text)
  on public.ticket_messages to authenticated;

create policy "staff read sla policies" on public.sla_policies
  for select to authenticated using (public.has_role('viewer'));
create policy "admins update sla policies" on public.sla_policies
  for update to authenticated using (public.has_role('admin')) with check (public.has_role('admin'));

create policy "staff read tickets" on public.tickets
  for select to authenticated using (public.has_role('viewer'));
create policy "agents create tickets" on public.tickets
  for insert to authenticated with check (public.has_role('agent'));
create policy "agents update tickets" on public.tickets
  for update to authenticated using (public.has_role('agent')) with check (public.has_role('agent'));
create policy "admins delete tickets" on public.tickets
  for delete to authenticated using (public.has_role('admin'));

create policy "staff read ticket messages" on public.ticket_messages
  for select to authenticated using (public.has_role('viewer'));
-- Agents post replies and notes as themselves; customer/system messages only
-- come from server-side code using the service role.
create policy "agents post replies and notes" on public.ticket_messages
  for insert to authenticated
  with check (public.has_role('agent') and kind in ('agent', 'note') and author_staff_id = (select auth.uid()));

create policy "staff read ticket events" on public.ticket_events
  for select to authenticated using (public.has_role('viewer'));

-- Agents logging a phone/walk-in/web request on the customer's behalf: the
-- ticket and the customer's description are created together, with the
-- description recorded as the customer's message (agents can't insert
-- customer messages directly).
create function public.create_staff_ticket(
  subject text,
  requester_email text,
  requester_name text,
  description text,
  channel public.ticket_channel default 'phone',
  priority public.ticket_priority default 'normal',
  client_id uuid default null,
  product_id uuid default null
)
returns public.tickets
language plpgsql
security definer
set search_path = ''
as $$
declare
  t public.tickets;
begin
  if not public.has_role('agent') then
    raise exception 'permission denied' using errcode = 'insufficient_privilege';
  end if;
  insert into public.tickets (subject, requester_email, requester_name, channel, priority, client_id, product_id)
  values (trim(subject), lower(trim(requester_email)), coalesce(trim(requester_name), ''), channel, priority, client_id, product_id)
  returning * into t;
  if coalesce(trim(description), '') <> '' then
    insert into public.ticket_messages (ticket_id, kind, author_email, author_name, body_text)
    values (t.id, 'customer', t.requester_email, t.requester_name, trim(description));
  end if;
  return t;
end;
$$;

revoke execute on function public.create_staff_ticket(text, text, text, text, public.ticket_channel, public.ticket_priority, uuid, uuid)
  from public, anon;
grant execute on function public.create_staff_ticket(text, text, text, text, public.ticket_channel, public.ticket_priority, uuid, uuid)
  to authenticated;
